CREATE TABLE departments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE employees (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(160) NOT NULL UNIQUE, salary NUMERIC(12,2) NOT NULL, department_id BIGINT NOT NULL REFERENCES departments(id), version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE attendance (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, employee_id BIGINT NOT NULL REFERENCES employees(id), attendance_date DATE NOT NULL, status VARCHAR(16) NOT NULL, CONSTRAINT uk_attendance_employee_date UNIQUE(employee_id,attendance_date));